alter table public.plop_events add column if not exists details jsonb not null default '{}'::jsonb;
alter table public.plop_events drop constraint if exists plop_events_event_check;
alter table public.plop_events add constraint plop_events_event_check check (event = any(array['page_view','product_view','select_product','add_to_cart','remove_from_cart','checkout_started','order_sent','receipt_uploaded','whatsapp_click','instagram_click','email_click','ver_producto','agregar_seleccion','elegir_fecha','enviar_solicitud','clic_whatsapp','seguimiento_pedido','subir_comprobante','personalization_started','validation_error','submit_attempt','submit_error']::text[]));
alter table public.plop_events add constraint plop_events_details_check check (jsonb_typeof(details)='object' and details - array['field','type']::text[] = '{}'::jsonb and (not details ? 'field' or details->>'field' = any(array['name','phone','email','locality','date','consent','names','career','colors','phrase','choice']::text[])) and (not details ? 'type' or details->>'type' = any(array['required','format','technical']::text[])));
